from __future__ import annotations

import html
import json
from datetime import datetime
from pathlib import Path

from .external import CAPABILITIES
from .policy import POLICY_VERSION
from .public import public_release_view
from .registry import discover

MANIFEST_SCHEMA = "public_evidence_manifest.v1"
EVAL_VERSION = "external_read_only_failure.v1"


def esc(value) -> str: return html.escape(str(value if value is not None else ""))


def human_duration(start: str, end: str) -> str:
    seconds = max(0, int((datetime.fromisoformat(end.replace("Z", "+00:00")) - datetime.fromisoformat(start.replace("Z", "+00:00"))).total_seconds()))
    minutes, seconds = divmod(seconds, 60); hours, minutes = divmod(minutes, 60)
    return " ".join(part for part in (f"{hours}h" if hours else "", f"{minutes}m" if minutes else "", f"{seconds}s" if seconds or not hours else "") if part)


def completed_run(release: dict, receipt: dict, verified: dict) -> dict:
    public = public_release_view(release, discover())
    modules = dict(public["manager_selection"])
    modules["skipped_modules"] = [{**item, "reason": "No AI, analytics, retrieval, ranking or experimentation surface was detected."} if item.get("module_id") == "data" else item for item in modules.get("skipped_modules", [])]
    checks = public["checks"]
    before = next((c for c in checks if c.get("status") == 404), None); after = next((c for c in checks if c.get("status") == 200), None)
    finding = next((f for f in public["findings"] if f.get("blocking")), None)
    task = public["remediation"][0] if public["remediation"] else None
    decision = public["owner_decisions"][0] if public["owner_decisions"] else None
    if not all((before, after, finding, task, decision)) or finding.get("state") != "CLOSED" or task.get("auto_merge") is not False or decision.get("resolution") != "accepted_condition":
        raise ValueError("controlled release proof is incomplete")
    if receipt.get("release_id") != public["release_id"] or not receipt.get("session_id"):
        raise ValueError("controlled Hermes receipt does not match release")
    return {
        "schema_version": "completed_run.v1", "release_id": public["release_id"], "product": public["product"],
        "modules": modules, "verified_blocker": {"criterion_id": finding.get("criterion_id"), "title": finding.get("title"), "state": finding.get("state"), "evidence": finding.get("evidence", [])},
        "remediation": task, "before_after": {"before_http": 404, "after_http": 200, "same_url": before.get("target") == after.get("target"), "url": after.get("target")},
        "owner_decision": decision, "verdict": public["verdict"], "hermes": {"session_id": receipt["session_id"], "delegation_id": verified["delegation_id"], "recorded_session_duration": human_duration(receipt["started_at"], receipt["ended_at"])},
        "public_references": {**public["public_artifacts"], "repository_url": verified["repository_url"], "pr_url": verified["pr_url"], "evidence_comment_url": verified["evidence_comment_url"], "ci_url": verified["ci_url"]},
        "proof_counts": {"tests_passed": verified["tests_passed"], "evals_passed": verified["evals_passed"]},
        "submission_proof": {"ci_status": verified.get("ci_status", "passed"), "policy_gate": verified.get("policy_gate", "passed"), "policy_version": verified.get("policy_version", POLICY_VERSION), "eval_version": verified.get("eval_version", EVAL_VERSION), "deployed_commit": verified.get("deployed_commit"), "rollback_baseline_version_id": verified.get("rollback_baseline_version_id"), "generated_at": verified.get("generated_at"), "pr2_url": verified.get("pr2_url")},
    }


def public_evidence_manifest(run: dict) -> dict:
    refs=run["public_references"]; proof=run["submission_proof"]
    return {"schema_version":MANIFEST_SCHEMA,"generated_at":proof.get("generated_at"),"policy_version":proof["policy_version"],"eval_version":proof["eval_version"],"release_id":run["release_id"],"final_verdict":run["verdict"]["status"],"hermes":{"session_id":run["hermes"]["session_id"],"delegation_id":run["hermes"]["delegation_id"]},"modules":{"selected_modules":run["modules"]["selected_modules"],"skipped_modules":run["modules"]["skipped_modules"]},"http_evidence":{"before":404,"after":200,"same_url":run["before_after"]["same_url"],"url":run["before_after"]["url"]},"owner_decision":run["owner_decision"],"public_references":{"repository_url":refs["repository_url"],"pr_url":refs["pr_url"],"pr2_url":proof.get("pr2_url"),"evidence_comment_url":refs["evidence_comment_url"],"public_report_url":refs["report_url"]},"verification":{"tests_passed":run["proof_counts"]["tests_passed"],"evals_passed":run["proof_counts"]["evals_passed"],"ci_status":proof["ci_status"],"ci_url":refs["ci_url"],"external_read_only_policy_gate":proof["policy_gate"]},"auto_merge":False,"deployment":{"deployed_commit":proof.get("deployed_commit"),"rollback_baseline_version_id":proof.get("rollback_baseline_version_id")}}


def render_controlled_report(run: dict) -> str:
    manifest=public_evidence_manifest(run); refs=manifest["public_references"]
    return f"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>Shiproom release evidence</title><style>body{{max-width:960px;margin:40px auto;padding:20px;background:#f3f0e6;color:#10241c;font:17px/1.6 system-ui}}article{{background:white;border:1px solid #c9c7bb;border-radius:14px;padding:20px;margin:14px 0}}h1,h2{{font-family:Georgia,serif}}a{{color:#136147;font-weight:700}}@media print{{body{{background:#fff;margin:0}}article{{break-inside:avoid}}}}</style></head><body><main><h1>Controlled release evidence</h1><p><strong>{esc(manifest['final_verdict'].replace('_',' '))}</strong> · <code>{esc(manifest['release_id'])}</code></p><article><h2>Verified closure</h2><p>HTTP 404 → independently verified HTTP 200 on <a href='{esc(manifest['http_evidence']['url'])}'>the same public URL</a>. The blocker is closed.</p></article><article><h2>Owner condition</h2><p>{esc(manifest['owner_decision'].get('choice'))} · {esc(manifest['owner_decision'].get('resolution'))}</p></article><article><h2>Public receipts</h2><p><a href='{esc(refs['pr_url'])}'>PR #1</a> · <a href='{esc(refs['evidence_comment_url'])}'>Evidence comment</a> · <a href='/public_evidence_manifest.v1.json'>Evidence manifest</a></p><p><code>auto_merge=false</code></p></article></main></body></html>"""


def render_console(run: dict, canonical_url: str) -> str:
    product = run["product"]; refs = run["public_references"]; short_session = run["hermes"]["session_id"][-8:]
    css = """:root{--ink:#10241c;--paper:#f3f0e6;--card:#fff;--green:#136147;--lime:#d9efae;--red:#a43b35;--amber:#a76b12;--line:#c9c7bb;--muted:#58655f}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}a{color:var(--green);font-weight:700}main{max-width:1180px;margin:auto;padding:24px}.judge-nav{position:sticky;top:0;z-index:2;display:flex;gap:8px;overflow-x:auto;padding:10px;background:rgba(243,240,230,.96);border-bottom:1px solid var(--line)}.judge-nav a{white-space:nowrap;padding:7px 9px}.hero{min-height:92vh;display:grid;align-content:center;gap:22px}.eyebrow,.status{text-transform:uppercase;letter-spacing:.12em;font-weight:900;color:var(--green)}h1{font:800 clamp(55px,10vw,125px)/.84 Georgia,serif;margin:0}h2{font:750 clamp(30px,5vw,52px)/1 Georgia,serif}.lede{font-size:clamp(22px,3vw,36px);max-width:850px}.verdict{display:inline-block;padding:10px 18px;border:2px solid;border-radius:999px;font-weight:900}.proof{display:grid;grid-template-columns:1fr auto 1fr;gap:14px;align-items:center}.proof article,.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px;min-width:0}.proof strong{font:800 clamp(48px,8vw,90px)/1 Georgia}.proof .before{border-top:8px solid var(--red)}.proof .after{border-top:8px solid var(--green)}.arrow{font-size:34px}.actions{display:flex;flex-wrap:wrap;gap:12px}.button{display:inline-block;padding:13px 18px;border-radius:10px;background:var(--green);color:#fff;text-decoration:none}.button.secondary{background:transparent;color:var(--green);border:2px solid}section{padding:52px 0;border-top:1px solid var(--line)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:15px}.agent{border-top:8px solid var(--green)}.agent.skipped{border-top-color:var(--muted)}.agent.remediation{border-top-color:var(--amber)}.agent.verifier{outline:2px solid var(--green)}.process{display:flex;gap:8px;overflow-x:auto;padding-bottom:10px}.step{flex:1 0 180px;padding:14px;border:1px solid var(--line);border-radius:12px;background:#fff}.timeline{counter-reset:item}.event{display:grid;grid-template-columns:44px 1fr;gap:12px;margin:12px 0}.event:before{counter-increment:item;content:counter(item);display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:var(--green);color:white;font-weight:900}.tabs{display:flex;gap:8px;flex-wrap:wrap}.tabs button{padding:10px 14px;border:1px solid var(--line);border-radius:9px;background:#fff;font-weight:800}.audience{margin-top:18px}.legend span{display:inline-block;padding:7px 10px;margin:4px;border:1px solid;border-radius:999px}.hierarchy li{margin:8px 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:grid;gap:5px;font-weight:750}input,textarea{width:100%;padding:11px;border:1px solid #919b95;border-radius:8px;font:inherit}textarea{min-height:90px}.full{grid-column:1/-1}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0e211a;color:#eaf5ef;padding:18px;border-radius:12px}.proof-list{list-style:none;padding:0}.proof-list li{margin:8px 0}small{color:var(--muted)}@media(max-width:700px){.proof{grid-template-columns:1fr}.arrow{text-align:center;transform:rotate(90deg)}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{min-height:auto;padding:60px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.judge-nav,.actions,.tabs,form,script{display:none!important}body{background:#fff}.hero{min-height:auto}.card,.proof article{break-inside:avoid}}"""
    agents = [("Release Manager","completed","manager","Selected the reviewers and delegated their mandates"),("Product / UX reviewer","completed","reviewer","Reviewed promise and critical journey"),("Engineering / QA reviewer","completed","reviewer","Classified the verified route blocker"),("Design reviewer","completed","reviewer","Reviewed the public experience"),("Data / AI reviewer","skipped","skipped","No AI, analytics, retrieval, ranking or experimentation surface was detected."),("Engineering remediation specialist","completed","remediation","Received the blocker as a bounded remediation task; did not close its own finding"),("Independent verifier","completed","verifier","Reran the original failed check and independently closed the blocker")]
    agent_html = "".join(f"<article class='card agent {role}'><p class='status'>{s} · {role}</p><h3>{n}</h3><p>{d}</p></article>" for n,s,role,d in agents)
    events = ["Contract accepted","Product, Engineering and Design selected; Data skipped","Public journey failed with HTTP 404","Verified blocker created; release placed on HOLD","Bounded remediation completed on the recorded branch","Independent verifier observed HTTP 200","Owner accepted the beta promise condition","SHIP WITH CONDITIONS published"]
    event_html = "".join(f"<div class='event'><div><strong>{e}</strong></div></div>" for e in events)
    contract_caps = json.dumps({key: key == "inspect_public_surfaces" for key in sorted(CAPABILITIES)})
    script = """const form=document.querySelector('#release-form'),out=document.querySelector('#contract-output');function validHttps(v){{try{{let u=new URL(v);return u.protocol==='https:'&&!/localhost|127\\.0\\.0\\.1/i.test(u.hostname)}}catch{{return false}}}}function packet(){{let d=new FormData(form),repo=d.get('repository_url').trim(),live=d.get('live_url').trim();if(!validHttps(repo)||!validHttps(live))throw new Error('Repository and deployment must be public HTTPS URLs.');let vals={{target_user:d.get('target_user').trim(),product_promise:d.get('product_promise').trim(),critical_journey:d.get('critical_journey').trim()}};for(let [k,v] of Object.entries(vals))if(!v||v.length>500||/[A-Za-z]:\\\\|file:\\/\\//.test(v))throw new Error('Complete all fields without local paths; each field is limited to 500 characters.');return{{schema_version:'external_release_contract.v1',project_name:new URL(repo).pathname.split('/').filter(Boolean).pop()||'External project',repository_url:repo,pr_url:null,live_url:live,target_user:vals.target_user,product_promise:vals.product_promise,critical_journey:vals.critical_journey.split(/\\n|→/).map(x=>x.trim()).filter(Boolean).slice(0,12),non_goals:(d.get('non_goals')||'').split(/\\n|,/).map(x=>x.trim()).filter(Boolean).slice(0,12),owner_constraints:['Public read-only review'],capabilities:__CAPABILITIES__}}form.addEventListener('submit',e=>{{e.preventDefault();try{{out.textContent=JSON.stringify(packet(),null,2);out.hidden=false;document.querySelector('#contract-actions').hidden=false}}catch(x){{out.textContent=x.message;out.hidden=false}}}});document.querySelector('#copy-contract').onclick=()=>navigator.clipboard.writeText(out.textContent);document.querySelector('#download-contract').onclick=()=>{{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([out.textContent],{{type:'application/json'}}));a.download='shiproom-release-contract.json';a.click();URL.revokeObjectURL(a.href)}};document.querySelectorAll('[data-audience]').forEach(b=>b.onclick=()=>{{document.querySelectorAll('.audience').forEach(x=>x.hidden=x.id!==b.dataset.audience);}});"""
    script = script.replace("__CAPABILITIES__", contract_caps).replace("{{", "{").replace("}}", "}")
    pr2_html = f" · <a href='{esc(run['submission_proof']['pr2_url'])}'>PR #2</a>" if run["submission_proof"].get("pr2_url") else ""
    return f"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>Shiproom — Evidence-gated release assurance</title><meta name='description' content='Shiproom turns product promises into evidence-gated release verdicts.'><link rel='canonical' href='{esc(canonical_url)}/'><meta property='og:title' content='Shiproom · SHIP WITH CONDITIONS'><meta property='og:description' content='The code passed. The product failed its promise. Shiproom caught it.'><meta property='og:type' content='website'><meta property='og:url' content='{esc(canonical_url)}/'><style>{css}</style></head><body><main><nav class='judge-nav' aria-label='Judge navigation'><a href='#overview'>Overview</a><a href='#agency'>Agency</a><a href='#evidence'>Evidence</a><a href='#ceo'>CEO view</a><a href='#product'>Product view</a><a href='#engineering'>Engineering view</a><a href='#prepare'>Prepare a release</a><a href='#submission-proof'>Submission proof</a></nav><header id='overview' class='hero'><p class='eyebrow'>Evidence-gated release assurance</p><h1>Shiproom</h1><p class='lede'>The code passed. The product failed its promise.</p><p>{esc(product['promise'])}</p><p><span class='verdict'>SHIP WITH CONDITIONS</span></p><div class='proof' aria-label='Verified before and after evidence'><article class='before'><p class='status'>Before · verified blocker</p><strong>404</strong><p>The critical public result did not open.</p></article><div class='arrow' aria-hidden='true'>→</div><article class='after'><p class='status'>After · independently verified</p><strong>200</strong><p>The same URL opened after bounded remediation.</p></article></div><div class='actions'><a class='button' href='/reports/{esc(run['release_id'])}'>Explore full evidence</a><a class='button secondary' href='#prepare'>Prepare your own release</a></div><small>Public console online · Hermes execution runs locally through the Shiproom skill</small></header><section><h2>What happened</h2><div class='process'>{''.join(f'<div class="step">{esc(x)}</div>' for x in ['Declared ready','Critical journey failed','HOLD','Bounded remediation','Independent rerun','SHIP WITH CONDITIONS'])}</div></section><section id='agency'><h2>Actual agent organization</h2><p>The Release Manager selected and delegated the reviewers. The blocker became a remediation task; the remediation specialist could not close it. The independent verifier reran the original check. The owner handled only the product-promise decision.</p><div class='grid'>{agent_html}</div></section><section><h2>Controlled-run timeline</h2><div class='timeline'>{event_html}</div><p>Recorded judged-session duration: <strong>{esc(run['hermes']['recorded_session_duration'])}</strong>.</p></section><section><h2>Views for every release owner</h2><div class='tabs' aria-label='Audience views'><button type='button' data-audience='ceo'>CEO</button><button type='button' data-audience='product'>Product</button><button type='button' data-audience='engineering'>Engineering</button></div><article id='ceo' class='card audience'><h3>CEO</h3><p><strong>Verdict:</strong> SHIP WITH CONDITIONS. Initial risk: a verified public-journey blocker. Shiproom isolated and repaired the route defect on a branch without human intervention. The owner made one product-promise decision and accepted one remaining beta condition.</p></article><article id='product' class='card audience'><h3>Product</h3><p><strong>Target:</strong> {esc(product['target_user'])}. <strong>Promise:</strong> {esc(product['promise'])}</p><p>The promised public journey returned HTTP 404 rather than opening. After remediation it returned HTTP 200. The owner resolved the publication-promise conflict by accepting the explicit beta condition.</p></article><article id='engineering' class='card audience'><h3>Engineering</h3><p>HTTP 404 on <a href='{esc(run['before_after']['url'])}'>the failing public URL</a> was remediated on branch <code>{esc(run['remediation'].get('branch'))}</code> through <a href='{esc(refs['pr_url'])}'>PR #1</a>. The independent rerun returned HTTP 200. Protected route evidence remained intact and <code>auto_merge=false</code>.</p></article></section><section id='evidence'><h2>How Shiproom decides</h2><ol class='hierarchy'><li><strong>Live deterministic evidence</strong></li><li>Current release contract</li><li>Current repository and deployment state</li><li>Model-reviewed judgment</li><li>Agent report</li></ol><p>Model opinions may create recommendations but cannot close verified blockers. The fixer cannot verify its own work. Owner intent and accepted risk remain human-owned. Shiproom never auto-merged this release.</p><div class='legend'><span>Deterministically verified</span><span>Browser observed</span><span>Source backed</span><span>Model reviewed</span><span>Owner confirmed</span><span>Missing evidence</span></div></section><section id='prepare'><h2>Prepare a release review</h2><p>Create a valid contract for local Hermes execution. This form does not start a remote run.</p><form id='release-form' class='form-grid'><label>Public GitHub repository URL<input name='repository_url' type='url' maxlength='300' required placeholder='https://github.com/owner/repo'></label><label>Live deployment URL<input name='live_url' type='url' maxlength='300' required placeholder='https://example.com'></label><label>Target user<input name='target_user' maxlength='300' required></label><label>Product promise<input name='product_promise' maxlength='500' required></label><label class='full'>Critical journey<textarea name='critical_journey' maxlength='1000' required placeholder='One step per line'></textarea></label><label class='full'>Optional non-goals<textarea name='non_goals' maxlength='1000'></textarea></label><div class='full'><button class='button' type='submit'>Prepare a release review</button></div></form><pre id='contract-output' hidden></pre><div id='contract-actions' class='actions' hidden><button id='copy-contract' type='button'>Copy JSON</button><button id='download-contract' type='button'>Download JSON</button></div><p><strong>Next:</strong> Open Hermes in the Shiproom repository and invoke <code>/shiproom</code> with this release contract. <a href='/setup'>View setup instructions</a>.</p></section><section id='submission-proof'><h2>Verified buildathon proof.</h2><ul class='proof-list'><li>Release <code title='{esc(run['release_id'])}'>{esc(run['release_id'])}</code></li><li>Hermes session <code title='{esc(run['hermes']['session_id'])}'>…{esc(short_session)}</code></li><li>Delegation <code title='{esc(run['hermes']['delegation_id'])}'>{esc(run['hermes']['delegation_id'])}</code></li><li>{run['proof_counts']['tests_passed']} tests · {run['proof_counts']['evals_passed']} evals · <a href='{esc(refs['ci_url'])}'>CI {esc(run['submission_proof']['ci_status'])}</a></li><li>Hardened external read-only policy gate: {esc(run['submission_proof']['policy_gate'])}.</li><li><a href='{esc(refs['repository_url'])}'>GitHub repository</a> · <a href='{esc(refs['pr_url'])}'>PR #1</a>{pr2_html} · <a href='{esc(refs['evidence_comment_url'])}'>Evidence comment</a></li><li><a href='/reports/{esc(run['release_id'])}'>Detailed public report</a> · <a href='/public_evidence_manifest.v1.json'>Public evidence manifest</a> · <a href='{esc(canonical_url)}'>Stable Worker</a></li><li><code>auto_merge=false</code></li><li><a href='/shiproom-verdict.svg' download>Download verdict badge</a></li></ul></section></main><script>{script}</script></body></html>"""


def verdict_badge() -> str:
    return """<svg xmlns="http://www.w3.org/2000/svg" width="420" height="64" role="img" aria-label="Shiproom: Ship with conditions"><rect width="420" height="64" rx="12" fill="#10241c"/><text x="24" y="40" fill="#f3f0e6" font-family="system-ui,sans-serif" font-size="22" font-weight="700">Shiproom · SHIP WITH CONDITIONS</text></svg>"""


def setup_page() -> str:
    return """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Shiproom setup</title></head><body style="max-width:760px;margin:50px auto;padding:20px;font:18px/1.6 system-ui"><h1>Run Shiproom locally through Hermes</h1><ol><li>Clone <a href="https://github.com/kruthika-kumar/shiproom">the Shiproom repository</a>.</li><li>Install the Shiproom skill in your isolated Hermes profile.</li><li>Open Hermes in the repository.</li><li>Invoke <code>/shiproom</code> with the generated <code>external_release_contract.v1</code>.</li></ol><p>Hermes execution stays local. The public console does not provide a remote runner.</p><p><a href="/">Return to Shiproom</a></p></body></html>"""


def write_submission(release: dict, receipt: dict, verified: dict, output: Path) -> dict:
    run = completed_run(release, receipt, verified); output.mkdir(parents=True, exist_ok=True)
    (output / "completed_run.json").write_text(json.dumps(run, indent=2), encoding="utf-8")
    (output / "public_evidence_manifest.v1.json").write_text(json.dumps(public_evidence_manifest(run), indent=2), encoding="utf-8")
    (output / "index.html").write_text(render_console(run, verified["canonical_url"]), encoding="utf-8")
    (output / "release-report.html").write_text(render_controlled_report(run), encoding="utf-8")
    (output / "shiproom-verdict.svg").write_text(verdict_badge(), encoding="utf-8")
    (output / "setup.html").write_text(setup_page(), encoding="utf-8")
    return run
